CREATE TABLE IF NOT EXISTS crm_task_alerts (tenant_id BIGINT UNSIGNED NOT NULL, activity_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, alert_type VARCHAR(20) NOT NULL, delivered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(tenant_id,activity_id,user_id,alert_type), FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, FOREIGN KEY (activity_id) REFERENCES crm_activities(id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;